package snmp
import("bufio";"strings";"testing";"os";"path/filepath")
func TestCorpusIndependentLiteral(t *testing.T){const payload="first  \n\n#literal\n  last\\\"quote";raw:=".1.3.6.1.4.1.99999.1.0 = STRING: \""+payload+"\"\n.1.3.6.1.4.1.99999.2.0 = INTEGER: 7\n";s:=&corpusRecordsLocal{scanner:bufio.NewScanner(strings.NewReader(raw))};if !s.Scan(){t.Fatal("no record")};got,ok:=corpusLiteralStringLocal(s.Text());if !ok||got!=payload{t.Fatal("literal payload bytes changed")};if !s.Scan(){t.Fatal("next record swallowed")};if s.Scan(){t.Fatal("extra record")};p:=filepath.Join(t.TempDir(),"literal.walk");if err:=os.WriteFile(p,[]byte(raw),0600);err!=nil{t.Fatal(err)};r:=RunCorpusReplayLocal(p,false);if r.Status!="completed"||r.SourceEntries!=2||r.RejectedLines!=0||r.KeptValueChanges!=0||r.BERFailures!=0{t.Fatalf("literal agent replay failed: %+v",r)}}
